/// A simple service to test the various types of RPCs and experiment with
/// performance with various types of payload.
pub fn TestService(comptime UserDataType: type, comptime ErrorSet: type) type {
    return struct {
        pub const package = "grpc.testing";
        pub const service_name = "TestService";

        /// One empty request followed by one empty response.
        EmptyCall: *const fn (userdata: *UserDataType, request: Empty) ErrorSet!Empty,
        /// One request followed by one response.
        UnaryCall: *const fn (userdata: *UserDataType, request: SimpleRequest) ErrorSet!SimpleResponse,
        /// One request followed by one response. Response has cache control
        /// headers set such that a caching HTTP proxy (such as GFE) can
        /// satisfy subsequent requests.
        CacheableUnaryCall: *const fn (userdata: *UserDataType, request: SimpleRequest) ErrorSet!SimpleResponse,
        /// One request followed by a sequence of responses (streamed download).
        /// The server returns the payload with client desired type and sizes.
        StreamingOutputCall: *const fn (userdata: *UserDataType, request: StreamingOutputCallRequest, writer_queue: *std.Io.Queue(StreamingOutputCallResponse)) ErrorSet!void,
        /// A sequence of requests followed by one response (streamed upload).
        /// The server returns the aggregated size of client payload as the result.
        StreamingInputCall: *const fn (userdata: *UserDataType, reader_queue: *std.Io.Queue(StreamingInputCallRequest)) ErrorSet!StreamingInputCallResponse,
        /// A sequence of requests with each request served by the server immediately.
        /// As one request could lead to multiple responses, this interface
        /// demonstrates the idea of full duplexing.
        FullDuplexCall: *const fn (userdata: *UserDataType, reader_queue: *std.Io.Queue(StreamingOutputCallRequest), writer_queue: *std.Io.Queue(StreamingOutputCallResponse)) ErrorSet!void,
        /// A sequence of requests followed by a sequence of responses.
        /// The server buffers all the client requests and then serves them in order. A
        /// stream of responses are returned to the client when the server starts with
        /// first request.
        HalfDuplexCall: *const fn (userdata: *UserDataType, reader_queue: *std.Io.Queue(StreamingOutputCallRequest), writer_queue: *std.Io.Queue(StreamingOutputCallResponse)) ErrorSet!void,
        /// The test server will not implement this method. It will be used
        /// to test the behavior when clients call unimplemented methods.
        UnimplementedCall: *const fn (userdata: *UserDataType, request: Empty) ErrorSet!Empty,
    };
}

/// A simple service NOT implemented at servers so clients can test for
/// that case.
pub fn UnimplementedService(comptime UserDataType: type, comptime ErrorSet: type) type {
    return struct {
        pub const package = "grpc.testing";
        pub const service_name = "UnimplementedService";

        /// A call that no server should implement
        UnimplementedCall: *const fn (userdata: *UserDataType, request: Empty) ErrorSet!Empty,
    };
}

