/// Hook service. Used to keep Kubernetes from shutting the pod down.
pub fn HookService(comptime UserDataType: type, comptime ErrorSet: type) type {
    return struct {
        pub const package = "grpc.testing";
        pub const service_name = "HookService";

        /// Sends a request that will "hang" until the return status is set by a call
        /// to a SetReturnStatus
        Hook: *const fn (userdata: *UserDataType, request: Empty) ErrorSet!Empty,
        /// Sets a return status for pending and upcoming calls to Hook
        SetReturnStatus: *const fn (userdata: *UserDataType, request: SetReturnStatusRequest) ErrorSet!Empty,
        /// Clears the return status. Incoming calls to Hook will "hang"
        ClearReturnStatus: *const fn (userdata: *UserDataType, request: Empty) ErrorSet!Empty,
    };
}

